class Lift extends StatefulWidget {
  const Lift({super.key,required this.child,required this.onTap,this.semanticLabel});final Widget child;final VoidCallback? onTap;final String? semanticLabel;
  @override State<Lift> createState()=>_LiftState();
}
class _LiftState extends State<Lift>{bool hover=false,down=false;@override Widget build(BuildContext context){final reduced=MediaQuery.disableAnimationsOf(context);return Semantics(label:widget.semanticLabel,button:true,child:MouseRegion(cursor:widget.onTap==null?SystemMouseCursors.basic:SystemMouseCursors.click,onEnter:(_)=>setState(()=>hover=widget.onTap!=null),onExit:(_)=>setState((){hover=false;down=false;}),child:AnimatedContainer(duration:FinMotion.duration(context,FinMotion.hover),curve:FinMotion.curve,transform:Matrix4.translationValues(0,hover&&!reduced?-2:0,0),decoration:BoxDecoration(borderRadius:BorderRadius.circular(6),boxShadow:hover?[const BoxShadow(color:Colors.black38,blurRadius:12,offset:Offset(0,4))]:[]),child:AnimatedScale(scale:down && !reduced ? .985 : 1.0,duration:FinMotion.duration(context,FinMotion.press),child:Material(color:hover?FinTheme.slate:FinTheme.surface,borderRadius:BorderRadius.circular(6),clipBehavior:Clip.antiAlias,child:InkWell(onTap:widget.onTap,onHighlightChanged:(v)=>setState(()=>down=v),child:widget.child))))));}}
class BrandGlyph extends StatelessWidget{const BrandGlyph(this.index,{super.key,this.color=FinTheme.steel,this.size=20});final int index;final Color color;final double size;@override Widget build(BuildContext context)=>SizedBox.square(dimension:size,child:CustomPaint(painter:_Glyph(index,color)));}
class _Glyph extends CustomPainter{_Glyph(this.index,this.color);final int index;final Color color;@override void paint(Canvas c,Size s){c.save();c.scale(s.width/24,s.height/24);final p=Paint()..color=color..style=PaintingStyle.stroke..strokeWidth=1.55..strokeCap=StrokeCap.round..strokeJoin=StrokeJoin.round;void line(double a,double b,double x,double y)=>c.drawLine(Offset(a,b),Offset(x,y),p);void rect(double x,double y,double w,double h)=>c.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(x,y,w,h),const Radius.circular(1.8)),p);void circle(double x,double y,double r)=>c.drawCircle(Offset(x,y),r,p);switch(index){case 0:rect(3,3,7,8);rect(13,3,8,5);rect(3,14,7,7);rect(13,11,8,10);break;case 1:line(3,20,21,20);line(6,16,6,8);rect(4,10,4,4);line(12,17,12,3);rect(10,6,4,6);line(18,15,18,5);rect(16,8,4,5);break;case 2:c.drawArc(const Rect.fromLTWH(4,4,16,16),-.5,5.1,false,p);line(3,5,3,11);line(3,11,9,11);line(12,7,12,12);line(12,12,16,14);break;case 3:rect(3,7,18,13);line(8,7,8,4);line(8,4,16,4);line(16,4,16,7);line(3,12,21,12);circle(12,12,1.5);break;case 4:for(final x in [5.0,12.0,19.0]){circle(x,12,1.5);}break;case 5:circle(10,10,6);line(15,15,21,21);line(7,12,10,8);line(10,8,13,11);break;case 6:rect(4,4,16,16);line(8,15,8,10);line(12,15,12,7);line(16,15,16,12);break;case 7:for(final y in [4.0,10.0,16.0]){rect(3,y,18,4);line(6,y+2,8,y+2);}break;case 8:circle(12,8,4);c.drawArc(const Rect.fromLTWH(4,13,16,13),3.5,2.42,false,p);break;default:circle(12,12,8);circle(12,12,3);}c.restore();}@override bool shouldRepaint(covariant _Glyph old)=>old.index!=index||old.color!=color;}
Widget editorialImage(String name,{BoxFit fit=BoxFit.cover})=>Image.asset('assets/editorial/$name.jpg',fit:fit,cacheWidth:name=='skyline'?1600:900,filterQuality:FilterQuality.medium,excludeFromSemantics:true);
class EditorialCarousel extends StatefulWidget{const EditorialCarousel({super.key,required this.enabled,this.onResearch,this.onStory});final bool enabled;final VoidCallback? onResearch;final ValueChanged<int>? onStory;@override State<EditorialCarousel> createState()=>_EditorialCarouselState();}
class _EditorialCarouselState extends State<EditorialCarousel>{Timer? timer;int index=0;bool paused=false,hover=false;@override void didChangeDependencies(){super.didChangeDependencies();schedule();}@override void didUpdateWidget(covariant EditorialCarousel old){super.didUpdateWidget(old);if(old.enabled!=widget.enabled)schedule();}void schedule(){timer?.cancel();if(widget.enabled&&!paused&&!hover&&!MediaQuery.disableAnimationsOf(context)){timer=Timer.periodic(const Duration(seconds:7),(_){if(mounted&&TickerMode.of(context))setState(()=>index=(index+1)%stories.length);});}}@override void dispose(){timer?.cancel();super.dispose();}void go(int n){setState(()=>index=(n+stories.length)%stories.length);schedule();}@override Widget build(BuildContext context){final item=stories[index];return MouseRegion(onEnter:(_){hover=true;schedule();},onExit:(_){hover=false;schedule();},child:Container(decoration:BoxDecoration(color:FinTheme.surface,border:Border.all(color:FinTheme.border),borderRadius:BorderRadius.circular(6)),clipBehavior:Clip.antiAlias,child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Padding(padding:const EdgeInsets.fromLTRB(12,8,8,5),child:Row(children:[const Expanded(child:Text('HISTORY ARCHIVE',style:TextStyle(fontSize:10,letterSpacing:1.3,color:FinTheme.steel))),IconButton(onPressed:()=>go(index-1),icon:const Icon(Icons.chevron_left)),IconButton(onPressed:(){setState(()=>paused=!paused);schedule();},icon:Icon(paused?Icons.play_arrow:Icons.pause)),IconButton(onPressed:()=>go(index+1),icon:const Icon(Icons.chevron_right))])),SizedBox(height:168,child:AnimatedSwitcher(duration:FinMotion.duration(context,const Duration(milliseconds:480)),child:Stack(key:ValueKey(index),fit:StackFit.expand,children:[editorialImage(item.$1),const DecoratedBox(decoration:BoxDecoration(gradient:LinearGradient(begin:Alignment.topCenter,end:Alignment.bottomCenter,colors:[Colors.transparent,Color(0xE6090D16)]))),Positioned(left:13,right:13,bottom:12,child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(item.$3,style:const TextStyle(color:FinTheme.ivory,fontSize:10,letterSpacing:1.1)),const SizedBox(height:5),Text(item.$2,maxLines:2,overflow:TextOverflow.ellipsis,style:const TextStyle(fontSize:20,fontWeight:FontWeight.w500)),Text(item.$4,maxLines:2,overflow:TextOverflow.ellipsis,style:const TextStyle(fontSize:11))]))]))),Padding(padding:const EdgeInsets.all(9),child:Row(children:[for(var i=0;i<stories.length;i++)Expanded(child:GestureDetector(onTap:()=>go(i),child:AnimatedContainer(duration:FinMotion.hover,height:3,margin:const EdgeInsets.only(right:3),color:i==index?FinTheme.ivory:FinTheme.border))),const SizedBox(width:8),if(widget.onStory!=null||widget.onResearch!=null)TextButton(onPressed:widget.onStory==null?widget.onResearch:()=>widget.onStory!(index),child:const Text('Explore'))])),const Padding(padding:EdgeInsets.fromLTRB(12,0,12,9),child:Text('Editorial imagery · thematic context, not event photography',style:TextStyle(fontSize:9,color:FinTheme.steel)))])));}}
class VisualLibrary extends StatelessWidget{const VisualLibrary({super.key});@override Widget build(BuildContext context){const items=[('wall_street','US markets'),('london','European markets'),('tokyo','Asian markets'),('studio','Trading research'),('signal','Quantitative signals'),('terminal','Execution workspace')];return LayoutBuilder(builder:(_,b){final n=b.maxWidth>=900?3:b.maxWidth>=500?2:1;return Wrap(spacing:8,runSpacing:8,children:[for(final item in items) SizedBox(width:(b.maxWidth-8*(n-1))/n,child:ClipRRect(borderRadius:BorderRadius.circular(5),child:Stack(children:[SizedBox(height:118,width:double.infinity,child:editorialImage(item.$1)),Positioned(left:0,right:0,bottom:0,child:Container(color:const Color(0xCC090D16),padding:const EdgeInsets.all(10),child:Text(item.$2))) ]))) ]);});}}

